const mediaGallery: MediaItem[] = [
  { id: 'm1', titleKey: 'media1Title', type: 'photo', url: 'data:image/jpeg;base64,', date: '2025-05-10' },
  { id: 'm2', titleKey: 'media2Title', type: 'video', url: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTQA1a_BaKQSEKUSSUVx1D8msg5WEMl4jpvsg&s', date: '2025-05-05' },
  { id: 'm3', titleKey: 'media3Title', type: 'photo', url: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSRAzkPtlhayydm8GsFsCInlE18mUljourm3Q&s', date: '2025-04-28' },
];

const formatDate = (dateString: string): string => {
  try {
    return new Date(dateString).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
  } catch {
    return dateString;
  }
};

const getUniqueYears = (items: NewsItem[]): string[] => {
  const years = items.map(item => new Date(item.date).getFullYear().toString());
  return Array.from(new Set(years)).sort().reverse();
};

const categoryLabels: Record<NewsCategory, string> = {
  investigations: 'categoryInvestigations',
  cybercrime: 'categoryCybercrime',
  terrorism: 'categoryTerrorism',
  'public-safety': 'categoryPublicSafety',
  community: 'categoryCommunity',
  'press-release': 'categoryPressRelease',
};

const NewsPage: React.FC = () => {
  const { t } = useTranslation();
  const [activeCategory, setActiveCategory] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [archiveYear, setArchiveYear] = useState<string>('all');
  const [archiveMonth, setArchiveMonth] = useState<string>('all');

  const featured = newsData.find(item => item.type === 'featured');
  const pressReleases = newsData.filter(item => item.type === 'press-release');
  const safetyAlerts = newsData.filter(item => item.type === 'alert');
  const successStories = newsData.filter(item => item.type === 'success');
  const events = newsData.filter(item => item.type === 'event');
  const years = getUniqueYears(newsData);
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  const filteredNews = useMemo(() => {
    let filtered = newsData.filter(item => item.type !== 'featured');
    if (activeCategory !== 'all') filtered = filtered.filter(item => item.category === activeCategory);
    if (searchTerm.trim()) {
      const term = searchTerm.toLowerCase();
      filtered = filtered.filter(item => 
        t(item.titleKey).toLowerCase().includes(term) || 
        t(item.summaryKey).toLowerCase().includes(term)
      );
    }
    if (archiveYear !== 'all') {
      filtered = filtered.filter(item => new Date(item.date).getFullYear().toString() === archiveYear);
      if (archiveMonth !== 'all') {
        filtered = filtered.filter(item => new Date(item.date).getMonth().toString() === archiveMonth);
      }
    }
    return filtered.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [activeCategory, searchTerm, archiveYear, archiveMonth, t]);

  const handleYearChange = (year: string) => {
    setArchiveYear(year);
    if (year === 'all') setArchiveMonth('all');
  };

  return (
    <div className="bg-white min-h-screen">
      <Navbar/>
      {/* Hero Section with Search */}
      <div className="bg-[#0B3B60] text-white py-12 px-4">
        <div className="max-w-7xl mx-auto">
          <h1 className="text-3xl md:text-4xl font-bold flex items-center gap-2 mb-4">
            <FaNewspaper /> {t('newsTitle')}
          </h1>
          <div className="relative max-w-xl">
            <FaSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
            <input
              type="text"
              placeholder={t('searchNews')}
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 rounded-lg text-gray-900 focus:outline-none focus:ring-2 focus:ring-[#FFD700]"
            />
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-8 md:py-12">
        {/* 1. Featured News */}
        {featured && (
          <div className="mb-12">
            <div className="bg-white rounded-2xl shadow-xl overflow-hidden md:flex">
              <div className="md:w-1/2">
                <img src={featured.imageUrl} alt={t(featured.titleKey)} className="w-full h-64 md:h-full object-cover" />
              </div>
              <div className="p-6 md:w-1/2 flex flex-col justify-center">
                <span className="text-xs bg-[#B22234] text-white px-2 py-1 rounded-full w-fit mb-2">{t('featured')}</span>
                <h2 className="text-2xl md:text-3xl font-bold text-[#0B3B60] mb-3">{t(featured.titleKey)}</h2>
                <p className="text-gray-600 mb-4">{t(featured.summaryKey)}</p>
                <a href="#" className="inline-flex items-center gap-2 text-[#B22234] font-semibold hover:underline">
                  {t('readMore')} <FaExternalLinkAlt size={12} />
                </a>
              </div>
            </div>
          </div>
        )}

        {/* 2. Press Releases */}
        {pressReleases.length > 0 && (
          <div className="mb-12">
            <h2 className="text-2xl font-bold text-[#0B3B60] border-l-4 border-[#B22234] pl-3 mb-6">{t('pressReleases')}</h2>
            <div className="grid md:grid-cols-2 gap-6">
              {pressReleases.map(pr => (
                <div key={pr.id} className="bg-gray-50 rounded-xl overflow-hidden shadow hover:shadow-lg transition flex flex-col sm:flex-row">
                  <img src={pr.imageUrl} alt={t(pr.titleKey)} className="sm:w-32 h-32 object-cover" />
                  <div className="p-4 flex-1">
                    <h3 className="font-bold text-[#0B3B60]">{t(pr.titleKey)}</h3>
                    <p className="text-sm text-gray-500 mt-1">{formatDate(pr.date)}</p>
                    <p className="text-sm text-gray-600 mt-2">{t(pr.summaryKey)}</p>
                    <a href="#" className="inline-block mt-2 text-[#B22234] text-sm font-semibold hover:underline">{t('fullRelease')}</a>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 3. Most Recent News with Filters & Archive */}
        <div className="mb-12">
          <div className="flex flex-wrap justify-between items-center gap-4 mb-6">
            <h2 className="text-2xl font-bold text-[#0B3B60] border-l-4 border-[#B22234] pl-3">{t('mostRecentNews')}</h2>
            <div className="flex flex-wrap gap-2">
              <FaFilter className="text-gray-500 self-center" />
              <select
                value={activeCategory}
                onChange={(e) => setActiveCategory(e.target.value)}
                className="border rounded-lg px-2 py-1 text-sm focus:ring-2 focus:ring-[#B22234]"
              >
                <option value="all">{t('allCategories')}</option>
                {Object.entries(categoryLabels).map(([value, labelKey]) => (
                  <option key={value} value={value}>{t(labelKey)}</option>
                ))}
              </select>
            </div>
          </div>

          {/* Archive Dropdowns */}
          <div className="flex flex-wrap gap-4 mb-6 bg-gray-100 p-3 rounded-lg">
            <div className="flex items-center gap-2">
              <FaCalendarAlt className="text-gray-500" />
              <select 
                value={archiveYear} 
                onChange={(e) => handleYearChange(e.target.value)} 
                className="border rounded px-2 py-1 text-sm focus:ring-2 focus:ring-[#B22234]"
              >
                <option value="all">{t('allYears')}</option>
                {years.map(y => <option key={y} value={y}>{y}</option>)}
              </select>
            </div>
            {archiveYear !== 'all' && (
              <div className="flex items-center gap-2">
                <FaCalendarAlt className="text-gray-500" />
                <select 
                  value={archiveMonth} 
                  onChange={(e) => setArchiveMonth(e.target.value)} 
                  className="border rounded px-2 py-1 text-sm focus:ring-2 focus:ring-[#B22234]"
                >
                  <option value="all">{t('allMonths')}</option>
                  {months.map((m, idx) => <option key={m} value={idx}>{m}</option>)}
                </select>
              </div>
            )}
          </div>

          {/* News Grid */}
          {filteredNews.length === 0 ? (
            <div className="text-center py-12 bg-gray-50 rounded-xl">
              <p className="text-gray-500">{t('noNewsMatch')}</p>
            </div>
          ) : (
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredNews.map(article => (
                <div key={article.id} className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-xl transition flex flex-col h-full">
                  <img src={article.imageUrl} alt={t(article.titleKey)} className="h-48 w-full object-cover" />
                  <div className="p-5 flex flex-col flex-grow">
                    <div className="flex justify-between items-start gap-2">
                      <h3 className="font-bold text-[#0B3B60] text-lg">{t(article.titleKey)}</h3>
                      <span className="text-xs bg-gray-200 px-2 py-1 rounded-full shrink-0">{formatDate(article.date)}</span>
                    </div>
                    <p className="text-gray-600 text-sm mt-2 flex-grow">{t(article.summaryKey)}</p>
                    <a href="#" className="mt-4 text-[#B22234] text-sm font-semibold inline-flex items-center gap-1 hover:underline">{t('readMore')} →</a>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* 4. Public Safety Alerts */}
        {safetyAlerts.length > 0 && (
          <div className="mb-12 bg-red-50 rounded-xl p-6 border-l-4 border-[#B22234]">
            <h2 className="text-2xl font-bold text-[#B22234] flex items-center gap-2 mb-4">
              <FaExclamationTriangle /> {t('publicSafetyAlerts')}
            </h2>
            <div className="grid sm:grid-cols-2 gap-4">
              {safetyAlerts.map(alert => (
                <div key={alert.id} className="bg-white rounded-lg p-4 shadow">
                  <h3 className="font-bold text-[#0B3B60]">{t(alert.titleKey)}</h3>
                  <p className="text-sm text-gray-600 mt-1">{t(alert.summaryKey)}</p>
                  <div className="mt-2 text-xs text-gray-400">{formatDate(alert.date)}</div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 5. Success Stories */}
        {successStories.length > 0 && (
          <div className="mb-12">
            <h2 className="text-2xl font-bold text-[#0B3B60] flex items-center gap-2 mb-4">
              <FaStar className="text-[#FFD700]" /> {t('successStories')}
            </h2>
            <div className="grid md:grid-cols-2 gap-6">
              {successStories.map(story => (
                <div key={story.id} className="bg-gray-50 rounded-xl p-5 flex gap-4 items-start">
                  <img src={story.imageUrl} alt={t(story.titleKey)} className="w-20 h-20 rounded-lg object-cover" />
                  <div>
                    <h3 className="font-bold text-[#0B3B60]">{t(story.titleKey)}</h3>
                    <p className="text-sm text-gray-600">{t(story.summaryKey)}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 6. Events & Conferences */}
        {events.length > 0 && (
          <div className="mb-12">
            <h2 className="text-2xl font-bold text-[#0B3B60] flex items-center gap-2 mb-4">
              <FaCalendarCheck /> {t('eventsConferences')}
            </h2>
            <div className="grid sm:grid-cols-2 gap-4">
              {events.map(ev => (
                <div key={ev.id} className="border rounded-lg p-4 flex items-start gap-3 hover:shadow transition">
                  <div className="bg-[#0B3B60] text-white rounded-lg p-2 text-center w-16">
                    <div className="text-lg font-bold">{new Date(ev.date).getDate()}</div>
                    <div className="text-xs">{new Date(ev.date).toLocaleString('default', { month: 'short' })}</div>
                  </div>
                  <div>
                    <h3 className="font-bold text-[#0B3B60]">{t(ev.titleKey)}</h3>
                    <p className="text-sm text-gray-500">{t(ev.summaryKey)}</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 7. News Categories (visual badges) */}
        <div className="mb-12">
          <h2 className="text-2xl font-bold text-[#0B3B60] mb-4">{t('newsCategories')}</h2>
          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setActiveCategory('all')}
              className={`px-4 py-2 rounded-full text-sm font-medium transition ${
                activeCategory === 'all' ? 'bg-[#B22234] text-white' : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
              {t('allCategories')}
            </button>
            {Object.entries(categoryLabels).map(([value, labelKey]) => (
              <button
                key={value}
                onClick={() => setActiveCategory(value)}
                className={`px-4 py-2 rounded-full text-sm font-medium transition ${
                  activeCategory === value ? 'bg-[#B22234] text-white' : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                }`}
              >
                {t(labelKey)}
              </button>
            ))}
          </div>
        </div>

        {/* 8. Media Gallery */}
        <div>
          <h2 className="text-2xl font-bold text-[#0B3B60] flex items-center gap-2 mb-4">
            <FaPhotoVideo /> {t('mediaGallery')}
          </h2>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {mediaGallery.map(media => (
              <div key={media.id} className="bg-gray-50 rounded-xl overflow-hidden shadow hover:shadow-lg transition">
                {media.type === 'photo' ? (
                  <img src={media.url} alt={t(media.titleKey)} className="w-full h-48 object-cover" />
                ) : (
                  <div className="relative pt-[56.25%]">
                    <iframe src={media.url} title={t(media.titleKey)} className="absolute top-0 left-0 w-full h-full" frameBorder="0" allowFullScreen></iframe>
                  </div>
                )}
                <div className="p-3">
                  <p className="font-medium text-[#0B3B60]">{t(media.titleKey)}</p>
                  <p className="text-xs text-gray-400">{formatDate(media.date)}</p>
                </div>
              </div>
            ))}
          </div>
          <div className="text-center mt-6">
            <a href="#" className="inline-flex items-center gap-2 text-[#B22234] font-semibold hover:underline">
              {t('viewFullGallery')} →
            </a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default NewsPage;